    ['problem solving', 'functional fixedness', 'the tendency to think of things only in terms of their usual functions', 'A person needs to tighten a screw but does not think of using a coin as a screwdriver.'],
    ['problem solving', 'divergent thinking', 'creative thinking that expands the number of possible solutions', 'Students list as many uses for a paper clip as they can in two minutes.'],
    ['problem solving', 'convergent thinking', 'thinking that narrows the possible solutions to the single best one', 'A student uses the clues in a question to narrow four choices down to the one correct answer.'],
    ['bias', 'confirmation bias', 'a tendency to search for information that supports one’s preconceptions and to ignore contradictory evidence', 'A voter who supports a candidate reads only news stories that praise that candidate.'],
    ['bias', 'availability heuristic', 'estimating the likelihood of events based on how easily they come to mind', 'After seeing news coverage of a plane crash, a traveler decides to drive because flying now seems more dangerous.'],
    ['bias', 'representativeness heuristic', 'judging likelihood by how well something matches a particular prototype', 'Told that a quiet, organized person loves books, people guess she is a librarian rather than a salesperson, even though salespeople are far more common.'],
    ['bias', 'framing', 'the way an issue is posed, which can significantly affect decisions and judgments', 'Shoppers prefer ground beef labeled “80% lean” over beef labeled “20% fat.”'],
    ['bias', 'gambler’s fallacy', 'the belief that the chance of a random event depends on previous outcomes', 'After a coin lands heads five times in a row, a player bets on tails because it seems “due.”'],
    ['bias', 'sunk-cost fallacy', 'continuing to invest in something because of what has already been invested, even when quitting would be better', 'A man stays through a terrible movie because he already paid for the ticket.'],
    ['bias', 'belief perseverance', 'clinging to one’s initial beliefs even after the basis for them has been discredited', 'Even after a study linking a vaccine to illness is retracted as fraudulent, some people still believe the link is real.'],
    ['bias', 'overconfidence', 'the tendency to be more confident than correct', 'Students predict they will finish a paper in two days, but it takes them a week.'],
    ['memory system', 'sensory memory', 'the immediate, very brief recording of sensory information', 'For a split second after a camera flash, you can still “see” the room.'],
    ['memory system', 'iconic memory', 'a momentary visual sensory memory lasting a fraction of a second', 'Participants shown a grid of letters for a split second can report any one row if cued immediately, but the image fades within a second.'],
    ['memory system', 'echoic memory', 'a momentary auditory sensory memory lasting a few seconds', 'You ask a friend, “What did you say?” and then recall her words before she repeats them.'],
    ['memory system', 'short-term memory', 'activated memory that holds a few items briefly before they are stored or forgotten', 'You remember a phone number just long enough to dial it, and then it is gone.'],
    ['memory system', 'working memory', 'the active processing of information in short-term memory, including a central executive, phonological loop, and visuospatial sketchpad', 'A student mentally rearranges the words of a sentence while also picturing where they appear on the page.'],
    ['memory system', 'long-term memory', 'the relatively permanent and limitless storehouse of the memory system', 'You still remember the name of your first-grade teacher years later.'],
    ['memory type', 'explicit memory', 'memory of facts and experiences that one can consciously know and declare', 'A student consciously recalls the definition of photosynthesis for a test.'],
    ['memory type', 'episodic memory', 'explicit memory of personally experienced events', 'You remember the details of your tenth birthday party.'],
    ['memory type', 'semantic memory', 'explicit memory of facts and general knowledge', 'You know that Paris is the capital of France but do not remember when you learned it.'],
    ['memory type', 'implicit memory', 'retention of learned skills or conditioned associations without conscious recollection', 'A patient with amnesia improves at a puzzle each day even though she does not remember doing it before.'],
    ['memory type', 'procedural memory', 'implicit memory of how to perform skills', 'Years after last riding one, you get on a bicycle and ride without thinking about it.'],
    ['memory type', 'prospective memory', 'remembering to do something in the future', 'You remember to take your medication at 8 p.m.'],
    ['encoding', 'chunking', 'organizing items into familiar, manageable units', 'You remember the letters FBICIANBA as three groups: FBI, CIA, and NBA.'],
    ['encoding', 'method of loci', 'a mnemonic that associates items to remember with locations along a familiar route', 'To remember a speech, a student pictures each point in a different room of her house.'],
    ['encoding', 'spacing effect', 'the tendency for distributed study to produce better long-term retention than massed practice', 'A student who studies vocabulary 20 minutes a day for a week remembers more than one who studies for 2 hours the night before.'],
    ['encoding', 'deep processing', 'encoding based on the meaning of words, which tends to produce better retention', 'Students who decide whether each word fits in a sentence remember more words than those who count the letters.'],
    ['encoding', 'shallow processing', 'encoding on a basic level, based on the structure or appearance of words', 'Students asked whether each word is printed in capital letters later recall very few of the words.'],
    ['encoding', 'self-reference effect', 'the tendency to remember information better when it is related to oneself', 'Participants who rate whether adjectives describe themselves remember more of the adjectives.'],
    ['encoding', 'automatic processing', 'unconscious encoding of incidental information such as space, time, and frequency', 'Without trying, you remember where on the page you read a particular fact.'],
    ['encoding', 'effortful processing', 'encoding that requires attention and conscious effort', 'A student repeats vocabulary words aloud and quizzes herself until she knows them.'],
    ['retrieval', 'recall', 'retrieving information that is not currently in awareness but was learned earlier, without cues', 'On a fill-in-the-blank test, a student must produce the answers without any choices to pick from.'],
    ['retrieval', 'recognition', 'identifying items previously learned, as on a multiple-choice test', 'You cannot name all your classmates, but you can pick out their photos in a yearbook.'],
    ['retrieval', 'relearning', 'learning something more quickly when learning it a second time', 'A college student who took Spanish in high school relearns forgotten vocabulary faster than her classmates learn it.'],
    ['retrieval', 'context-dependent memory', 'better recall when in the same environment as during encoding', 'Divers who learn words underwater recall them better underwater than on land.'],
    ['retrieval', 'state-dependent memory', 'better recall when in the same physical or internal state as during encoding', 'Information learned after drinking coffee is recalled best after drinking coffee again.'],
    ['retrieval', 'mood-congruent memory', 'the tendency to recall experiences that match one’s current mood', 'When feeling sad, a man easily recalls other disappointing times in his life.'],
    ['retrieval', 'testing effect', 'enhanced memory after retrieving, rather than simply rereading, information', 'Students who quiz themselves remember more on the final than students who only reread their notes.'],
    ['retrieval', 'serial position effect', 'the tendency to recall the first and last items in a list best', 'After hearing a 15-item grocery list once, a shopper remembers the first few and last few items best.'],
    ['forgetting', 'proactive interference', 'the disruptive effect of older learning on recall of new information', 'After moving, you keep writing your old address on forms.'],
    ['forgetting', 'retroactive interference', 'the disruptive effect of new learning on recall of old information', 'After learning Spanish, a student has trouble remembering the French words she learned earlier.'],
    ['forgetting', 'encoding failure', 'forgetting because information never entered long-term memory', 'You cannot draw the details of a penny even though you have seen thousands of them.'],
    ['forgetting', 'forgetting curve', 'the pattern in which most forgetting occurs soon after learning and then levels off', 'Ebbinghaus found that he forgot most nonsense syllables within the first day, after which forgetting slowed.'],
    ['forgetting', 'misinformation effect', 'incorporating misleading information into one’s memory of an event', 'Witnesses asked how fast cars were going when they “smashed” later remember broken glass that was not there.'],
    ['forgetting', 'source amnesia', 'attributing to the wrong source an event one experienced, heard about, read about, or imagined', 'You remember a funny story but wrongly believe your friend told it, when you actually saw it online.'],
    ['forgetting', 'anterograde amnesia', 'an inability to form new memories', 'After brain surgery, a patient remembers his childhood but cannot remember people he met yesterday.'],
    ['forgetting', 'retrograde amnesia', 'an inability to retrieve information from one’s past', 'After a car accident, a woman cannot remember the weeks before the crash.'],
    ['forgetting', 'tip-of-the-tongue phenomenon', 'the feeling of being sure one knows something but being temporarily unable to retrieve it', 'You know the actor’s name starts with “M” but cannot quite say it.'],
    ['intelligence', 'general intelligence (g)', 'a general ability that underlies specific mental abilities and is measured by every task on an intelligence test', 'People who score well on vocabulary tests also tend to score well on spatial and math tests.'],
    ['intelligence', 'multiple intelligences', 'Gardner’s idea that people have several relatively independent kinds of intelligence', 'A psychologist argues that a gifted dancer and a gifted mathematician display different types of intelligence.'],
    ['intelligence', 'fluid intelligence', 'the ability to reason speedily and abstractly, which tends to decrease in late adulthood', 'A 25-year-old solves unfamiliar logic puzzles faster than her 70-year-old grandfather.'],
    ['intelligence', 'crystallized intelligence', 'accumulated knowledge and verbal skills, which tend to increase with age', 'A 70-year-old has a larger vocabulary than his 25-year-old granddaughter.'],
    ['intelligence', 'Flynn effect', 'the rise in intelligence test performance over the past century', 'Average raw scores on intelligence tests rose from one generation to the next, so the tests had to be renormed.'],
    ['intelligence', 'stereotype threat', 'a concern that one will be evaluated based on a negative stereotype, which can lower performance', 'Women who are told a math test shows gender differences score lower than women told it does not.'],
    ['intelligence', 'emotional intelligence', 'the ability to perceive, understand, manage, and use emotions', 'A manager notices that an employee is upset and responds calmly and supportively.'],
    ['testing', 'standardization', 'defining uniform testing procedures and meaningful scores by comparison with a pretested group', 'A new test is given to a large, representative sample under identical instructions so later scores can be compared with theirs.'],
    ['testing', 'reliability', 'the extent to which a test yields consistent results', 'Students who take the same test twice, a month apart, get very similar scores.'],
    ['testing', 'validity', 'the extent to which a test measures or predicts what it is supposed to', 'A driving test that requires actually driving on the road measures the skills it is meant to measure.'],
    ['testing', 'predictive validity', 'the success with which a test predicts the behavior it is designed to predict', 'Scores on a college entrance exam correlate with students’ first-year college grades.'],
    ['testing', 'achievement test', 'a test designed to assess what a person has learned', 'At the end of the year, students take an exam on the material taught in their history course.'],
    ['testing', 'aptitude test', 'a test designed to predict a person’s future performance or capacity to learn', 'A company gives applicants a test to predict how quickly they will learn to write computer code.'],
    ['testing', 'split-half reliability', 'consistency between scores on two halves of the same test', 'Researchers compare each student’s score on the odd-numbered items with the score on the even-numbered items.'],
    ['research design', 'independent variable', 'the factor that the experimenter manipulates', 'In a caffeine study, researchers decide how much caffeine each group receives.'],
    ['research design', 'dependent variable', 'the outcome that is measured to see whether it changes in response to the manipulated variable', 'In a caffeine study, researchers record each participant’s reaction time.'],
    ['research design', 'confounding variable', 'a factor other than the one being studied that might influence the results', 'Students in the caffeine group happened to sleep more the night before, which could also explain their faster reaction times.'],
    ['research design', 'random assignment', 'assigning participants to experimental and control groups by chance', 'Each participant draws a number from a hat to decide whether they join the caffeine group or the placebo group.'],
    ['research design', 'random sampling', 'selecting participants so that every member of the population has an equal chance of being chosen', 'Researchers randomly select 300 names from the full list of students at a university.'],
    ['research design', 'control group', 'the group in an experiment that does not receive the treatment and serves as a comparison', 'One group receives a decaffeinated drink that looks and tastes identical so it can be compared with the caffeine group.'],
    ['research design', 'placebo effect', 'results caused by expectations alone', 'Participants who believe they drank coffee report feeling more alert even though their drink had no caffeine.'],
    ['research design', 'double-blind procedure', 'a procedure in which neither the participants nor the researchers collecting data know who received the treatment', 'Neither the participants nor the assistants measuring reaction times know who received caffeine.'],
    ['research design', 'operational definition', 'a precise statement of the procedures used to measure a variable', 'A researcher defines aggression as the number of times a child hits a punching doll during a 10-minute play session.'],
    ['research design', 'experimenter bias', 'a researcher’s expectations unintentionally influencing the results', 'A researcher who expects caffeine to help unintentionally gives more encouragement to the caffeine group.'],
    ['research design', 'social desirability bias', 'the tendency for participants to respond in ways that make them look good', 'Survey respondents underreport how much junk food they eat because they want to appear healthy.']
