const fmt = value => String(Number(value.toFixed(2))).replace(/^-/, '−');

// Builds one generated question; returns null unless the four choices are distinct.
function make(unit, family, key, prompt, choices, explanation) {
  if (new Set(choices).size !== 4 || choices.some(choice => /NaN|undefined/.test(choice))) return null;
  return { id: 'psy-' + unit + '-' + family + '-' + key, family, prompt, choices, answer: 0, explanation };
}

// Three different wrong options from a pool, chosen by position so the set stays stable.
function others(pool, correct, index) {
  const rest = pool.filter(item => item !== correct);
  return [0, 1, 2].map(step => rest[(index + step) % rest.length]);
}

const slug = text => text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

function conceptQuestions(unit) {
  const list = concepts[unit] ?? [];
  const groups = new Map();
  for (const [group, term] of list) {
    if (!groups.has(group)) groups.set(group, []);
    groups.get(group).push(term);
  }
  return list.flatMap(([group, term, definition, example]) => {
    const pool = groups.get(group);
    const index = pool.indexOf(term);
    const wrong = others(pool, term, index);
    const stem = stems[group] ?? 'Which concept does this best illustrate?';
    return [
      make(unit, 'define-' + slug(group), slug(term), `Which term refers to ${definition}?`, [term, ...wrong],
        `${term[0].toUpperCase() + term.slice(1)} refers to ${definition}.`),
      make(unit, 'apply-' + slug(group), slug(term), stem ? `${example} ${stem}` : example, [term, ...others(pool, term, index + 1)],
        `This illustrates ${term}: ${definition}.`)
    ];
  });
}

const statistics = {
  1: () => [
    ['hours of sleep reported by five students', [2, 2, 5, 8, 13]],
    ['scores on a 20-point memory quiz', [4, 4, 7, 9, 16]],
    ['minutes participants took to solve a puzzle', [10, 10, 14, 15, 21]],
    ['reaction times (in hundredths of a second)', [60, 70, 70, 75, 80, 95]],
    ['words recalled from a list', [3, 3, 4, 9, 11]],
    ['hours of weekly exercise reported by six adults', [12, 15, 15, 18, 20, 28]],
    ['errors made on a driving simulator', [5, 5, 8, 10, 17]],
    ['days of sleep diary entries completed', [20, 20, 24, 25, 36]],
    ['nightmares reported in a month', [1, 1, 2, 6, 10]],
    ['math problems solved in five minutes', [7, 7, 9, 12, 20]],
    ['scores on an anxiety scale', [30, 40, 40, 45, 60, 65]],
    ['cups of coffee consumed per week', [3, 3, 6, 8, 15]],
    ['scores on a 100-point practice exam', [50, 50, 58, 62, 80]]
  ].flatMap(([label, data], index) => {
    const sorted = [...data].sort((a, b) => a - b);
    const n = sorted.length;
    const mean = sorted.reduce((sum, v) => sum + v, 0) / n;
    const median = n % 2 ? sorted[(n - 1) / 2] : (sorted[n / 2 - 1] + sorted[n / 2]) / 2;
    const counts = new Map();
    sorted.forEach(v => counts.set(v, (counts.get(v) ?? 0) + 1));
    const mode = [...counts.entries()].sort((a, b) => b[1] - a[1])[0][0];
    const range = sorted[n - 1] - sorted[0];
    const values = { mean, median, mode, range };
    const how = {
      mean: `add the values (${fmt(mean * n)}) and divide by ${n}`,
      median: n % 2 ? 'take the middle value of the ordered list' : 'average the two middle values of the ordered list',
      mode: 'take the most frequent value',
      range: `subtract the lowest value from the highest (${sorted[n - 1]} − ${sorted[0]})`
    };
    return Object.keys(values).map(measure => make(1, 'stats-' + measure, index + '-' + measure,
      `A researcher records these ${label}: ${data.join(', ')}. What is the ${measure}?`,
      [fmt(values[measure]), ...Object.keys(values).filter(m => m !== measure).map(m => fmt(values[m]))],
      `To find the ${measure}, ${how[measure]}: ${fmt(values[measure])}.`));
  }),
  2: () => {
    const distributions = [['IQ scores', 100, 15], ['SAT section scores', 500, 100], ['heights of adult women in inches', 64, 3], ['reaction times in milliseconds', 250, 20]];
    const pool = ['68%', '95%', '99.7%', '34%', '13.5%', '16%', '2.5%', '84%', '50%', '47.5%'];
    const questions = (mean, sd) => [
      ['within1', `between ${mean - sd} and ${mean + sd}`, '68%', 'About 68% of scores fall within one standard deviation of the mean.'],
      ['within2', `between ${mean - 2 * sd} and ${mean + 2 * sd}`, '95%', 'About 95% of scores fall within two standard deviations of the mean.'],
      ['within3', `between ${mean - 3 * sd} and ${mean + 3 * sd}`, '99.7%', 'About 99.7% of scores fall within three standard deviations of the mean.'],
      ['meanTo1', `between ${mean} and ${mean + sd}`, '34%', 'Half of the middle 68%, or about 34%, falls between the mean and one standard deviation above it.'],
      ['1to2', `between ${mean + sd} and ${mean + 2 * sd}`, '13.5%', 'Between one and two standard deviations above the mean is (95% − 68%) ÷ 2 = 13.5%.'],
      ['above1', `above ${mean + sd}`, '16%', 'About 16% of scores are more than one standard deviation above the mean: (100% − 68%) ÷ 2.'],
      ['above2', `above ${mean + 2 * sd}`, '2.5%', 'About 2.5% of scores are more than two standard deviations above the mean: (100% − 95%) ÷ 2.'],
      ['below1', `below ${mean + sd}`, '84%', 'About 84% of scores fall below one standard deviation above the mean: 50% + 34%.']
    ];
    const normal = distributions.flatMap(([label, mean, sd], d) => questions(mean, sd).map(([key, range, answer, explanation], q) =>
      make(2, 'stats-normal', d + '-' + key, `${label[0].toUpperCase() + label.slice(1)} are normally distributed with a mean of ${mean} and a standard deviation of ${sd}. About what percentage of scores fall ${range}?`,
        [answer, ...others(pool, answer, q + d)], explanation)));
    const zScores = distributions.flatMap(([label, mean, sd], d) => [1.5, -1, 2, -2.5].map((z, i) => {
      const score = mean + z * sd;
      return make(2, 'stats-z', d + '-' + i, `${label[0].toUpperCase() + label.slice(1)} have a mean of ${mean} and a standard deviation of ${sd}. What is the z-score of a score of ${fmt(score)}?`,
        [fmt(z), fmt(-z), fmt(score - mean), fmt(z * 2)], `z = (score − mean) ÷ SD = (${fmt(score)} − ${mean}) ÷ ${sd} = ${fmt(z)}.`);
    }));
    return [...normal, ...zScores];
  },
  4: () => [
    [-0.85, 0.62, 0.30, -0.10], [0.45, -0.72, 0.68, 0.05], [0.91, -0.35, 0.50, -0.88], [-0.60, 0.59, -0.20, 0.40],
    [0.15, -0.95, 0.80, 0.33], [-0.40, -0.25, 0.38, 0.12], [0.70, -0.71, 0.10, -0.50], [0.02, -0.15, 0.12, -0.30],
    [-0.55, 0.20, 0.53, -0.08], [0.66, 0.64, -0.67, 0.10], [0.25, -0.18, 0.90, -0.92], [-0.33, 0.29, -0.81, 0.79]
  ].flatMap((set, index) => {
    const show = r => (r < 0 ? '−' : '+') + Math.abs(r).toFixed(2);
    const byStrength = [...set].sort((a, b) => Math.abs(b) - Math.abs(a));
    const strongest = byStrength[0];
    const weakest = byStrength[3];
    return [
      make(4, 'stats-correlation', 'strong-' + index, `Four studies report these correlation coefficients: ${set.map(show).join(', ')}. Which indicates the strongest relationship between the variables?`,
        [show(strongest), ...set.filter(r => r !== strongest).map(show)], `Strength depends on the absolute value of r, not its sign; ${show(strongest)} is farthest from 0.`),
      make(4, 'stats-correlation', 'weak-' + index, `Four studies report these correlation coefficients: ${set.map(show).join(', ')}. Which indicates the weakest relationship between the variables?`,
        [show(weakest), ...set.filter(r => r !== weakest).map(show)], `The coefficient closest to 0, ${show(weakest)}, shows the weakest relationship.`)
    ];
  })
};

function writtenQuestion(unit, entry, index) {
  const id = 'psy-' + unit + '-written-' + index;
  if (!Array.isArray(entry)) return { ...entry, id, answer: 0, family: entry.family };
  const [family, prompt, correct, a, b, c, explanation] = entry;
  return { id, family: 'scenario-' + family + '-' + (index % 3), prompt, choices: [correct, a, b, c], answer: 0, explanation };
}

const cache = new Map();

export function psychologyQuestions(unit) {
  if (!cache.has(unit)) {
    const items = (written[unit - 1] ?? []).map((entry, index) => writtenQuestion(unit, entry, index));
    const generated = [...conceptQuestions(unit), ...(statistics[unit]?.() ?? [])].filter(Boolean);
    const unique = new Map();
    for (const item of [...items, ...generated]) if (!unique.has(item.id)) unique.set(item.id, item);
    cache.set(unit, [...unique.values()]);
  }
  return cache.get(unit);
}
